mapper.select:
    SELECT
      memberid,
      email
    FROM
      ttokssaemdb.member
    WHERE
		  memberid = #{memberid}
		  AND membername = #{membername}
      AND contact = #{contact}

mapper.update:
UPDATE ttokssaemdb.member
  SET
  memberpw = hex(aes_encrypt(#{after_pw},'ttokssaem_2022@'))
WHERE
  member.branchid = #{branchid}
  AND member.memberid = #{memberid}

UPDATE ttokssaemdb.member
  SET
  membername = #{membername},
  contact = #{contact},
  email = #{email}
WHERE
  member.branchid = #{branchid}
  AND member.memberid = #{memberid}

UPDATE ttokssaemdb.member
  SET
  push = #{push}
WHERE
  member.branchid = #{branchid}
  AND member.memberid = #{memberid}
